namespace sv_97d3369990344817b35d11fe9a4fbaa1.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit (user session).
/// Each SignalR circuit gets its own instance, so concurrent users are isolated.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public event Action? OnWarehouseChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A — Downtown"),
        ("WH-002", "Warehouse B — Eastside"),
        ("WH-003", "Warehouse C — Airport"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public void Dispose()
    {
        OnWarehouseChanged = null;
    }
}

namespace sv_97d3369990344817b35d11fe9a4fbaa1.Services;

/// <summary>
/// Simulates a database query that returns the count of low-stock items for a warehouse.
/// Registered as a singleton because it is stateless — the randomness simulates varying DB results.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB access with a small delay and random result.
        int count = _random.Next(0, 16);
        return Task.FromResult(count);
    }
}

namespace sv_97d3369990344817b35d11fe9a4fbaa1.Services;

/// <summary>
/// Scoped service that manages the 10-second polling timer for low-stock alerts.
/// When polling is active it queries <see cref="InventoryAlertService"/> for the current warehouse
/// and broadcasts the result to all subscribed components via <see cref="OnAlertCountChanged"/>.
/// </summary>
public sealed class AlertPollingService : IDisposable
{
    private readonly InventoryAlertService _alertService;
    private readonly WarehouseStateService _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _currentCount;

    public int CurrentAlertCount => _currentCount;

    /// <summary>
    /// Raised whenever a new alert count is fetched. All subscribed components should re-render.
    /// The int parameter is the new low-stock count.
    /// </summary>
    public event Action<int>? OnAlertCountChanged;

    public AlertPollingService(InventoryAlertService alertService, WarehouseStateService warehouseState)
    {
        _alertService = alertService;
        _warehouseState = warehouseState;
    }

    /// <summary>
    /// Called by components that want polling to be active. Polling starts on the first subscriber
    /// and stops when the last subscriber leaves.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    public void Unsubscribe()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            StopPolling();
        }
    }

    /// <summary>
    /// Triggers an immediate poll outside the timer cycle (e.g. after a warehouse change).
    /// </summary>
    public async Task RefreshNowAsync()
    {
        var count = await _alertService.GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        _currentCount = count;
        OnAlertCountChanged?.Invoke(count);
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            // Fetch immediately on start, then every 10 seconds.
            await PollOnceAsync();

            while (await _timer.WaitForNextTickAsync(token))
            {
                await PollOnceAsync();
            }
        }, token);
    }

    private async Task PollOnceAsync()
    {
        try
        {
            var count = await _alertService.GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
            _currentCount = count;
            OnAlertCountChanged?.Invoke(count);
        }
        catch (Exception)
        {
            // Swallow — polling failures should not crash the circuit.
        }
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        StopPolling();
        OnAlertCountChanged = null;
    }
}

