@using sv_97d3369990344817b35d11fe9a4fbaa1.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label text-white mb-1" for="warehouseSelect">Current Warehouse</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            value="@WarehouseState.SelectedWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    public void Dispose() { }
}

@using sv_97d3369990344817b35d11fe9a4fbaa1.Services
@inject AlertPollingService Polling
@implements IDisposable
@rendermode InteractiveServer

<span class="alert-badge @(_count > 0 ? "has-alerts" : "")">
    🔔 @_count
</span>

@code {
    private int _count;

    protected override void OnInitialized()
    {
        _count = Polling.CurrentAlertCount;
        Polling.OnAlertCountChanged += HandleAlertCountChanged;
    }

    private void HandleAlertCountChanged(int newCount)
    {
        InvokeAsync(() =>
        {
            _count = newCount;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        Polling.OnAlertCountChanged -= HandleAlertCountChanged;
    }
}

