@page "/"
@inject WarehouseStateService WarehouseState
@inject AlertPollingService Polling
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="card-text fs-5">@GetWarehouseName()</p>
                <p class="text-muted">ID: @WarehouseState.SelectedWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card @(_alertCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-2 fw-bold @(_alertCount > 0 ? "text-danger" : "text-success")">
                    @_alertCount
                </p>
                <p class="text-muted">Items below minimum level — refreshes every 10 s</p>
            </div>
        </div>
    </div>
</div>

@code {
    private int _alertCount;

    protected override void OnInitialized()
    {
        _alertCount = Polling.CurrentAlertCount;
        Polling.OnAlertCountChanged += HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;

        // Start polling when the dashboard becomes visible.
        Polling.Subscribe();
    }

    private void HandleAlertCountChanged(int count)
    {
        InvokeAsync(() =>
        {
            _alertCount = count;
            StateHasChanged();
        });
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately refresh alerts for the newly selected warehouse.
        await InvokeAsync(async () =>
        {
            await Polling.RefreshNowAsync();
            StateHasChanged();
        });
    }

    private string GetWarehouseName()
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.SelectedWarehouseId).Name
            ?? WarehouseState.SelectedWarehouseId;
    }

    public void Dispose()
    {
        Polling.OnAlertCountChanged -= HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;

        // Stop polling when the user leaves the dashboard.
        Polling.Unsubscribe();
    }
}

